    <div class="rating" id="rating"></div>

    <script>
        function rate() {
            const review = document.getElementById('review').value;
            const rating = prompt("Zenbat zaharra da idazlanak? (1-5)");

            if (rating) {
                let stars = '';
                for (let i = 0; i < rating; i++) {
                    stars += '★';
                }
                document.getElementById('rating').innerText = `Balorazioa: ${stars} (${rating}/5)`;
                document.getElementById('review').value = review + "\n\n" + stars;
            } else {
                alert("Mesedez, sartu balorazio bat.");
            }
        }
    </script>
